#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>

class Matrix {
    std::size_t rows_, cols_;
    std::vector<int> data_;
    static std::size_t checkedCount(std::size_t r, std::size_t c) {
        if (c != 0 && r > std::numeric_limits<std::size_t>::max() / c)
            throw std::length_error("row times column overflow");
        const std::size_t count = r * c;
        if (count > std::vector<int>().max_size())
            throw std::length_error("too many int elements");
        return count;
    }
public:
    Matrix(std::size_t r, std::size_t c) : rows_(r), cols_(c), data_(checkedCount(r,c), 0) {}
    // 크기가 고정된 소유자입니다. 복사 생성만 허용하고 재대입·이동은 막습니다.
    Matrix(const Matrix&) = default;
    Matrix& operator=(const Matrix&) = delete;
    Matrix(Matrix&&) = delete;
    Matrix& operator=(Matrix&&) = delete;
    int& at(std::size_t r, std::size_t c) {
        if (r >= rows_ || c >= cols_) throw std::out_of_range("matrix index");
        return data_[r * cols_ + c];
    }
    const int& at(std::size_t r, std::size_t c) const {
        if (r >= rows_ || c >= cols_) throw std::out_of_range("matrix index");
        return data_[r * cols_ + c];
    }
};
int main() {
    long long shapes = 0, cells = 0;
    for (std::size_t r = 0; r <= 12; ++r) for (std::size_t c = 0; c <= 12; ++c) {
        Matrix m(r,c);
        for (std::size_t i = 0; i < r; ++i) for (std::size_t j = 0; j < c; ++j) {
            assert(m.at(i,j) == 0);
            m.at(i,j) = static_cast<int>(i * 100 + j);
            assert(&m.at(i,j) == &m.at(0,0) + i*c + j);
            ++cells;
        }
        const Matrix copy = m;  // vector의 값 복사: 저장 공간도 독립입니다.
        for (std::size_t i = 0; i < r; ++i) for (std::size_t j = 0; j < c; ++j)
            assert(copy.at(i,j) == static_cast<int>(i*100+j));
        if (r && c) { m.at(0,0) = -1; assert(copy.at(0,0) == 0); }
        bool rejected = false;
        try { m.at(r,0) = 1; } catch (const std::out_of_range&) { rejected = true; }
        assert(rejected);
        ++shapes;
    }
    bool overflowRejected = false;
    try { Matrix tooLarge(std::numeric_limits<std::size_t>::max(), 2); }
    catch (const std::length_error&) { overflowRejected = true; }
    assert(overflowRejected);
    std::cout << "matrix shapes " << shapes << "; cells " << cells
              << "; bounds/overflow/deep-copy passed\n";
}
